"""1.0.1.dev5 test fixture (NOT runtime): 1.0.1.dev4's and 1.0.1.dev3's `estimator._grid` outputs, so that
tests/test_jax2_dt_rule_scope.py can check dev5's binning-aware scope (estimator note 16) against dev4's decision and
both grids BIT FOR BIT without git or the dev4 bytes.

dev4 was never committed: its estimator is read from the ARCHIVED candidate bytes,
reports/rel101/ADD3/dev4_candidate/mle_profile_jax2/estimator.py, sha256 checked against 1.0.1.dev4's VERSION_LOCK
entry (74c5201e..., PREREG_REL ADD3 draft of 2026-10-15, section 1). dev3's is `git show 787bbd1:` (sha256 dad4d050...).
What it stores (dev4_grids.json), every grid with the 1.0.1 class constants (floor_early, n_rule, early_all on):
  * "fine": for EVERY cohort of ../dt_rule_dev3/dev3_grids.json (key "cohorts", data as given) and EVERY view of its
    "windowed" cohorts (the view's prepared ages / events stored there), dev4's _grid(dt_rule=True) -- the fine-delta
    (delta/L ~ 0.01) and exact-time cases, where dev5 must take dev4's decision on the identical grid;
  * "binned": synthetic COARSELY RECORDED cohorts (delta/L ~ 0.1-0.25; deaths in 2-3 bins; ages stored verbatim, no
    RNG), each with dev3's _grid for dt_rule False / True (dev3's rule is unscoped) and dev4's _grid(dt_rule=True):
      - two masses 10 apart (the shape of v6 pure-k2-p05-c1-s0 = {90: 1049, 100: 951}): KM CV ~0.053, dev4 OUT of
        scope; CV_c ~0.043, dev5 IN -- at n 2,000, at n 120, and with censoring at the last bin;
      - two masses 20 apart with 7% in the upper bin (delta/L ~ 0.25): KM CV ~0.063 >= 0.05 and CV^2 < (delta/L)^2/12
        -- dev5's EDGE CASE (CV_c = 0.0), dev4 OUT;
      - two masses 10 apart with 5% in the upper bin (delta/L ~ 0.11): KM CV ~0.024, CV^2 < (delta/L)^2/12 -- the
        edge case where dev4 is already IN;
      - out of scope under both (the grid must stay dev3's dt_rule=False grid): two masses 10 apart at ages 50 / 60
        (KM CV ~0.09), three bins {90: 400, 100: 1200, 110: 400} (KM CV ~0.063, CV_c ~0.056);
      - one recorded age (KM CV 0: degenerate, out under both).
  * "binned_windowed" (added after the review of PREREG_REL ADD3 rev 2; the keys above are regenerated byte for
    byte): a COARSELY RECORDED, LEFT-TRUNCATED cohort with an OFF-GRID window -- two masses 10 apart ({90: 1049,
    100: 951}, delta 10) with 40 records censored at the window's close 104.5, window (85.5, 104.5) -- the shape of
    the library's windowed sharp-group c1 H views that dev5 adds. Per VIEW (J = window off, H = window on; prepare =
    dev3's observation_model, `git show 787bbd1`, sha256 deff521c..., relabel on) the prepared (ages, events),
    window_eff and snap counts, and dev3's _grid for dt_rule False / True and dev4's _grid(dt_rule=True). The H view's
    snap (hi 104.5 -> hi_eff 100: the deaths in hi_eff's bin censored, the censored ages moved down) changes L and the
    KM CV: KM CV ~0.053 (dev4 OUT), CV_c ~0.043 (dev5 IN, on dev3's dt_rule=True grid); the J view (the tie relabel
    censors the deaths at 100) reads KM CV ~0.075, CV_c ~0.069: OUT under both, where dev3's unscoped rule would cap.
usage: PYTHONPATH=<SRtools_kappa>:<repo> python make_dev4_grids.py   (writes dev4_grids.json next to this file)
"""
from __future__ import annotations

import hashlib
import importlib.util
import json
import os
import subprocess
import sys
import tempfile

HERE = os.path.dirname(os.path.abspath(__file__))
ROOT = os.path.abspath(os.path.join(HERE, "..", "..", "..", "..", ".."))
DEV3_COMMIT = "787bbd1c6e3bf8fefdef0a0dc090c0d6a22449c7"
DEV3_EST_SHA256 = "dad4d050f8ec5bc7ad0d4d47f978f5caad3c9f57272ec1ebb161ce3f10b676b8"
DEV4_EST = os.path.join(ROOT, "reports", "rel101", "ADD3", "dev4_candidate", "mle_profile_jax2", "estimator.py")
DEV4_EST_SHA256 = "74c5201ec98a5bf94ce71240d4195f7454249ceddf9ef7f8a338b196d5188b6a"
DEV3_FIXTURE = os.path.join(HERE, "..", "dt_rule_dev3", "dev3_grids.json")
GRID_KW = dict(floor_early=True, n_rule=True, early_all=True)

#: (tag, {age: deaths}, {age: censored}, delta, window) -- the windowed binned cohort (key "binned_windowed")
BINNED_WINDOWED = [
    ("win_bin2_offgrid", {90.0: 1049, 100.0: 951}, {104.5: 40}, 10.0, (85.5, 104.5)),
]
DEV3_OM_SHA256 = "deff521c80985a699f513758c494d9e0f3e8ab0fdf5cc97da292b342025d25d0"
#: (tag, {age: deaths}, {age: censored}, delta) -- ages stored verbatim
BINNED = [
    ("bin2_p05_n2000", {90.0: 1049, 100.0: 951}, {}, 10.0),
    ("bin2_n120", {90.0: 60, 100.0: 60}, {}, 10.0),
    ("bin2_censored", {90.0: 1000, 100.0: 700}, {100.0: 300}, 10.0),
    ("edge_dev4_out", {80.0: 1860, 100.0: 140}, {}, 20.0),
    ("edge_dev4_in", {90.0: 1900, 100.0: 100}, {}, 10.0),
    ("out_bin2_mean55", {50.0: 1000, 60.0: 1000}, {}, 10.0),
    ("out_bin3", {90.0: 400, 100.0: 1200, 110.0: 400}, {}, 10.0),
    ("degenerate_one_age", {100.0: 500}, {}, 10.0),
]


def load_bytes(src, key):
    d = tempfile.mkdtemp(prefix="dt_rule_dev4_")
    p = os.path.join(d, "estimator.py")
    with open(p, "wb") as fh:
        fh.write(src)
    spec = importlib.util.spec_from_file_location(key, p)
    m = importlib.util.module_from_spec(spec)
    sys.modules[spec.name] = m
    spec.loader.exec_module(m)
    return m


def estimators():
    src3 = subprocess.run(["git", "-C", ROOT, "show", f"{DEV3_COMMIT}:methods/mle_profile_jax2/estimator.py"],
                          capture_output=True, check=True).stdout
    if hashlib.sha256(src3).hexdigest() != DEV3_EST_SHA256:
        raise SystemExit("REFUSING: git's 787bbd1 estimator.py is not 1.0.1.dev3's")
    with open(DEV4_EST, "rb") as fh:
        src4 = fh.read()
    if hashlib.sha256(src4).hexdigest() != DEV4_EST_SHA256:
        raise SystemExit(f"REFUSING: {DEV4_EST} is not 1.0.1.dev4's estimator.py (sha256)")
    return load_bytes(src3, "dev4_fixture.est_dev3"), load_bytes(src4, "dev4_fixture.est_dev4")


def dev3_observation_model():
    src = subprocess.run(["git", "-C", ROOT, "show", f"{DEV3_COMMIT}:methods/mle_profile_jax2/observation_model.py"],
                         capture_output=True, check=True).stdout
    if hashlib.sha256(src).hexdigest() != DEV3_OM_SHA256:
        raise SystemExit("REFUSING: git's 787bbd1 observation_model.py is not 1.0.1.dev3's")
    return load_bytes(src, "dev4_fixture.om_dev3")


def grid(est, t, e, delta, x):
    L, kw, ceiling, floor = est._grid(t, e, delta, dt_rule=x, **GRID_KW)
    return dict(L=L, kw=kw, ceiling=ceiling, floor=floor)


def main():
    sys.path[:0] = [ROOT]
    import numpy as np
    if not hasattr(np, "trapz"):
        np.trapz = np.trapezoid
    from srbench import npcompat  # noqa: F401
    est3, est4 = estimators()
    with open(DEV3_FIXTURE) as fh:
        d3 = json.load(fh)
    fine = []
    for c in d3["cohorts"]:
        t, e = np.asarray(c["ages"], float), np.asarray(c["events"], int)
        g4 = grid(est4, t, e, c["delta"], True)
        fine.append(dict(tag=c["tag"], kind="cohort", view=None, delta=c["delta"], dev4_dt_rule_True=g4))
        print(f"fine {c['tag']:28s} cv={g4['floor']['grid_rule']['cv']:.5f} dev4 in={g4['floor']['grid_rule']['dt_in_scope']}"
              f" dt={g4['kw']['dt']:.3g}", flush=True)
    for c in d3["windowed"]:
        for view, v in sorted(c["views"].items()):
            t, e = np.asarray(v["prep_ages"], float), np.asarray(v["prep_events"], int)
            g4 = grid(est4, t, e, c["delta"], True)
            fine.append(dict(tag=c["tag"], kind="windowed", view=view, delta=c["delta"], dev4_dt_rule_True=g4))
            print(f"fine {c['tag']:22s} {view}     cv={g4['floor']['grid_rule']['cv']:.5f} dev4 in="
                  f"{g4['floor']['grid_rule']['dt_in_scope']} dt={g4['kw']['dt']:.3g}", flush=True)
    binned = []
    for tag, deaths, cens, delta in BINNED:
        ages = [a for a, k in sorted(deaths.items()) for _ in range(k)] + [a for a, k in sorted(cens.items())
                                                                           for _ in range(k)]
        events = [1] * sum(deaths.values()) + [0] * sum(cens.values())
        t, e = np.asarray(ages, float), np.asarray(events, int)
        out = dict(tag=tag, deaths={repr(a): k for a, k in deaths.items()}, censored={repr(a): k for a, k in cens.items()},
                   delta=delta, ages=[float(x) for x in t], events=[int(x) for x in e],
                   dev3_dt_rule_False=grid(est3, t, e, delta, False), dev3_dt_rule_True=grid(est3, t, e, delta, True),
                   dev4_dt_rule_True=grid(est4, t, e, delta, True))
        gr = out["dev4_dt_rule_True"]["floor"]["grid_rule"]
        out["km_cv"] = gr["cv"]
        out["dl"] = out["dev4_dt_rule_True"]["floor"]["dl"]
        binned.append(out)
        print(f"binned {tag:20s} n={t.size:5d} cv={gr['cv']:.5f} dl={out['dl']:.5f} dev4 in={gr['dt_in_scope']} "
              f"dt dev3 off/on={out['dev3_dt_rule_False']['kw']['dt']:.3g}/{out['dev3_dt_rule_True']['kw']['dt']:.3g} "
              f"dev4={out['dev4_dt_rule_True']['kw']['dt']:.3g}", flush=True)
    om = dev3_observation_model()
    binned_windowed = []
    for tag, deaths, cens, delta, window in BINNED_WINDOWED:
        ages = [a for a, k in sorted(deaths.items()) for _ in range(k)] + [a for a, k in sorted(cens.items())
                                                                           for _ in range(k)]
        events = [1] * sum(deaths.values()) + [0] * sum(cens.values())
        out = dict(tag=tag, deaths={repr(a): k for a, k in deaths.items()}, censored={repr(a): k for a, k in cens.items()},
                   delta=delta, window=list(window), ages=[float(x) for x in ages], events=[int(x) for x in events],
                   views={})
        for view in ("J", "H"):
            prep = om.prepare(ages, events, delta, window, window_on=(view == "H"), relabel_on=True)
            t, e = np.asarray(prep.ages, float), np.asarray(prep.events, int)
            snap = prep.record["window_snap"]
            v = dict(prep_ages=[float(x) for x in t], prep_events=[int(x) for x in e],
                     window_eff=(None if prep.window_eff is None else [float(x) for x in prep.window_eff]),
                     snap=(None if snap is None else {k: snap[k] for k in ("applied", "n_moved", "n_deaths_censored",
                                                                          "lo_eff", "hi_eff")}),
                     dev3_dt_rule_False=grid(est3, t, e, delta, False), dev3_dt_rule_True=grid(est3, t, e, delta, True),
                     dev4_dt_rule_True=grid(est4, t, e, delta, True))
            gr = v["dev4_dt_rule_True"]["floor"]["grid_rule"]
            v["km_cv"] = gr["cv"]
            v["dl"] = v["dev4_dt_rule_True"]["floor"]["dl"]
            out["views"][view] = v
            print(f"binned_windowed {tag} {view} n={t.size:5d} cv={gr['cv']:.5f} dl={v['dl']:.5f} dev4 in="
                  f"{gr['dt_in_scope']} window_eff={v['window_eff']} dt dev3 off/on="
                  f"{v['dev3_dt_rule_False']['kw']['dt']:.3g}/{v['dev3_dt_rule_True']['kw']['dt']:.3g} "
                  f"dev4={v['dev4_dt_rule_True']['kw']['dt']:.3g}", flush=True)
        binned_windowed.append(out)
    doc = dict(made_by="make_dev4_grids.py", dev3_commit=DEV3_COMMIT, dev3_estimator_sha256=DEV3_EST_SHA256,
               dev4_estimator=os.path.relpath(DEV4_EST, ROOT), dev4_estimator_sha256=DEV4_EST_SHA256,
               dev3_fixture_sha256=hashlib.sha256(open(DEV3_FIXTURE, "rb").read()).hexdigest(), grid_kw=GRID_KW,
               fine=fine, binned=binned, binned_windowed=binned_windowed, dev3_observation_model_sha256=DEV3_OM_SHA256)
    with open(os.path.join(HERE, "dev4_grids.json"), "w") as fh:
        json.dump(doc, fh, sort_keys=True, separators=(",", ":"))
        fh.write("\n")


if __name__ == "__main__":
    main()
